class SmartCache{constructor(options={}){this.memoryCache=new Map();this.maxMemorySize=options.maxMemorySize||100;this.ttl=options.ttl||7*24*60*60*1000;this.storagePrefix=options.storagePrefix||'ifsi_cache_';this.stats={memoryHits: 0,storageHits: 0,misses: 0,writes: 0};this.cleanExpired();}get(key){if(this.memoryCache.has(key)){const entry=this.memoryCache.get(key);if(!this.isExpired(entry)){this.stats.memoryHits++;return entry.value;}this.memoryCache.delete(key);}try{const storageKey=this.storagePrefix+key;const stored=localStorage.getItem(storageKey);if(stored){const entry=JSON.parse(stored);if(!this.isExpired(entry)){this.setMemory(key,entry.value,entry.timestamp);this.stats.storageHits++;return entry.value;}localStorage.removeItem(storageKey);}}catch(error){console.warn('Erreur lecture localStorage:',error);}this.stats.misses++;return null;}set(key,value,customTTL=null){const timestamp=Date.now();const ttl=customTTL||this.ttl;this.setMemory(key,value,timestamp);try{const storageKey=this.storagePrefix+key;const entry={value: value,timestamp: timestamp,expiresAt: timestamp+ttl};localStorage.setItem(storageKey,JSON.stringify(entry));this.stats.writes++;}catch(error){if(error.name==='QuotaExceededError'){console.warn('localStorage plein,nettoyage...');this.clearOldest(10);try{const storageKey=this.storagePrefix+key;const entry={value: value,timestamp: timestamp,expiresAt: timestamp+ttl};localStorage.setItem(storageKey,JSON.stringify(entry));}catch(retryError){console.error('Impossible de sauvegarder dans localStorage:',retryError);}}}}setMemory(key,value,timestamp){if(this.memoryCache.has(key)){this.memoryCache.delete(key);}if(this.memoryCache.size>=this.maxMemorySize){const firstKey=this.memoryCache.keys().next().value;this.memoryCache.delete(firstKey);}this.memoryCache.set(key,{value: value,timestamp: timestamp,expiresAt: timestamp+this.ttl});}isExpired(entry){return Date.now()>entry.expiresAt;}cleanExpired(){try{const keysToRemove=[];for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key&&key.startsWith(this.storagePrefix)){const stored=localStorage.getItem(key);if(stored){const entry=JSON.parse(stored);if(this.isExpired(entry)){keysToRemove.push(key);}}}}keysToRemove.forEach(key=>localStorage.removeItem(key));if(keysToRemove.length>0){console.log(`🧹 Nettoyé ${keysToRemove.length}entrées expirées du cache`);}}catch(error){console.warn('Erreur nettoyage cache:',error);}}clearOldest(count){try{const entries=[];for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key&&key.startsWith(this.storagePrefix)){const stored=localStorage.getItem(key);if(stored){const entry=JSON.parse(stored);entries.push({key,timestamp: entry.timestamp});}}}entries.sort((a,b)=>a.timestamp-b.timestamp);entries.slice(0,count).forEach(({key})=>{localStorage.removeItem(key);});console.log(`🧹 Supprimé ${count}entrées les plus anciennes`);}catch(error){console.warn('Erreur clearOldest:',error);}}clear(){this.memoryCache.clear();try{const keysToRemove=[];for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key&&key.startsWith(this.storagePrefix)){keysToRemove.push(key);}}keysToRemove.forEach(key=>localStorage.removeItem(key));}catch(error){console.warn('Erreur vidage cache:',error);}}async warmup(keys,fetchFunction){const missingKeys=keys.filter(key=>!this.get(key));if(missingKeys.length===0){console.log('✅ Cache déjà chaud,aucun préchargement nécessaire');return;}console.log(`🔥 Préchargement de ${missingKeys.length}entrées...`);try{const values=await fetchFunction(missingKeys);missingKeys.forEach((key,index)=>{if(values[index]){this.set(key,values[index]);}});console.log(`✅ ${missingKeys.length}entrées préchargées`);}catch(error){console.error('Erreur préchargement:',error);}}getStats(){const total=this.stats.memoryHits+this.stats.storageHits+this.stats.misses;const hitRate=total>0 ?((this.stats.memoryHits+this.stats.storageHits)/total*100).toFixed(1): 0;return{...this.stats,total,hitRate: `${hitRate}%`,memorySize: this.memoryCache.size,storageSize: this.getStorageSize()};}getStorageSize(){let count=0;try{for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key&&key.startsWith(this.storagePrefix)){count++;}}}catch(error){console.warn('Erreur comptage localStorage:',error);}return count;}logStats(){const stats=this.getStats();console.log('📊 Statistiques du cache:',stats);}}window.SmartCache=SmartCache;